INSERT INTO ioc (type, valeur, source) SELECT 'ip', source_ip, 'auth' FROM auth_logs WHERE resultat = 'echec' GROUP BY source_ip HAVING COUNT(*) >= 100;
WITH iv AS (SELECT host, domaine, ip_dest, horodatage, CAST(DATEDIFF(second, LAG(horodatage) OVER (PARTITION BY host, domaine ORDER BY horodatage), horodatage) AS FLOAT) AS dt FROM proxy_logs), st AS (SELECT host, domaine, ip_dest, COUNT(dt) AS n, AVG(dt) AS m, STDEVP(dt) AS sd FROM iv WHERE dt IS NOT NULL GROUP BY host, domaine, ip_dest HAVING COUNT(dt) >= 50) INSERT INTO ioc (type, valeur, source) SELECT DISTINCT 'domaine', domaine, 'proxy' FROM st WHERE sd / m < 0.05 AND domaine NOT IN (SELECT domaine FROM domaines_connus);
INSERT INTO ioc (type, valeur, source) SELECT 'domaine', domaine, 'dns' FROM dns_logs GROUP BY domaine HAVING AVG(CAST(LEN(requete) AS FLOAT)) > 40;

