CREATE TRIGGER trg_ioc ON proxy_logs AFTER INSERT AS
BEGIN
  INSERT INTO alertes (horodatage, host, cible)
  SELECT i.horodatage, i.host, i.domaine FROM inserted i
  WHERE i.domaine IN (SELECT valeur FROM ioc WHERE type = 'domaine') OR i.ip_dest IN (SELECT valeur FROM ioc WHERE type = 'ip');
END;
